from itertools import groupby

MAX_RUN = 9


def encode_runs(text):
    if any(char.isdigit() for char in text):
        raise ValueError("digits cannot be encoded")
    parts = []
    for char, group in groupby(text):
        length = len(list(group))
        while length > 0:
            chunk = min(length, MAX_RUN)
            parts.append(f"{char}{chunk}")
            length -= chunk
    return "".join(parts)

